#include "transform.h"
*/
import "C"
import "unsafe"

func TransformInPlace(data []float64, scale float64) error {
    if len(data) == 0 { return nil }
    C.transform_inplace((*C.double)(unsafe.Pointer(&data[0])), C.size_t(len(data)), C.double(scale))
    return nil
}
