  a := make([]float64, 1024)
  b := make([]float64, 1024)
  for i := range a { a[i] = float64(i) }
  for i := range b { b[i] = float64(i) }
  var wg sync.WaitGroup
  wg.Add(2)
  go func(){ defer wg.Done(); _ = t.TransformInPlace(a, 1.5) }()
  go func(){ defer wg.Done(); _ = t.TransformInPlace(b, 0.5) }()
  wg.Wait()
  fmt.Println(a[0], b[0])
