package cgHello
/*
#include "cgoc_hello.h"
#include <stdlib.h>
*/
import "C"
import (
  "errors"
  "unsafe"
)

func GetGreeting(name string) (string, error) {
  cname := C.CString(name)
  defer C.free(unsafe.Pointer(cname))
  var err C.int
  buf := C.greet(cname, &err)
  if buf == nil {
    switch err {
    default:
      return "", errors.New("greet failed")
    }
  }
  defer C.free(unsafe.Pointer(buf))
  goStr := C.GoString((*C.char)(unsafe.Pointer(buf)))
  return goStr, nil
}
```

